const API=window.__HATCHABLE__?.api||'/api';const $=s=>document.querySelector(s);const esc=s=>String(s??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));let projects=[];let editing={project:null,sections:[],images:[],originalSectionIds:[]};let mediaState={project:null,sections:[],images:[]};let supabaseClient=null;let editorLoadToken=0;let editorSaving=false;
function msg(el,text,error=false){if(!el)return;el.textContent=text;el.style.color=error?'#a53b35':''}
async function initSupabase(){const cfg=await fetch(API+'/admin-config',{credentials:'include'}).then(async r=>{const d=await r.json();if(!r.ok)throw Error(d.error||'Unable to load authentication configuration.');return d});if(!window.supabase){await new Promise((resolve,reject)=>{const s=document.createElement('script');s.src='https://cdn.jsdelivr.net/npm/@supabase/supabase-js@2';s.onload=resolve;s.onerror=()=>reject(Error('Unable to load Supabase authentication.'));document.head.appendChild(s)})}supabaseClient=window.supabase.createClient(cfg.url,cfg.publishableKey,{auth:{persistSession:true,autoRefreshToken:true,detectSessionInUrl:true}});const {data,error}=await supabaseClient.auth.getSession();if(error||!data?.session)throw Error('Please sign in to the admin panel.');return data.session}
async function api(path,opts={}){const headers=opts.body instanceof FormData?{}:{'Content-Type':'application/json'};let authHeaders={};if(supabaseClient){const sessionData=await supabaseClient.auth.getSession().catch(()=>null);const token=sessionData?.data?.session?.access_token;if(token)authHeaders.Authorization=`Bearer ${token}`;}const r=await fetch(API+path,{...opts,credentials:'include',redirect:'manual',headers:{...headers,...authHeaders,...(opts.headers||{})}});let d={};try{d=await r.json()}catch{}if(r.status===401||r.type==='opaqueredirect'){location.replace('/admin/login/');throw Error('Redirecting to admin sign-in…')}if(r.status===403)throw Error(d.error||'Admin access required.');if(!r.ok)throw Error(d.error||'Request failed.');return d}
