function renderProjects(){const search=($('#projectSearch').value||'').toLowerCase();const filter=$('#statusFilter').value;const list=projects.filter(p=>(filter==='all'||p.status===filter)&&(`${p.title} ${p.category}`.toLowerCase().includes(search)));if(!list.length){$('#projectList').innerHTML='<div class="panel">No case studies match your search.</div>';return}$('#projectList').innerHTML=list.map(p=>`<div class="project-row"><img class="thumb" src="${esc(p.cover_image_url||'')}" alt=""><div><h3>${esc(p.title)}</h3><p>${esc(p.category)} · ${esc(p.duration||'')} · <span class="status ${p.status==='draft'?'draft':''}">${esc(p.status)}</span></p></div><div class="project-actions"><span class="muted">#${esc(p.sort_order)}</span><button class="secondary edit-project" data-id="${esc(p.id)}">Edit</button><button class="secondary manage-media" data-id="${esc(p.id)}">Media</button></div></div>`).join('');document.querySelectorAll('.edit-project').forEach(b=>b.onclick=()=>openEditor(projects.find(p=>p.id===b.dataset.id)));document.querySelectorAll('.manage-media').forEach(b=>b.onclick=()=>openMediaForProject(b.dataset.id))}
