function tusEncode(value){return btoa(unescape(encodeURIComponent(String(value))));}
async function resumableUpload(file,prep){if(!supabaseClient)await initSupabase();const token=String(prep.uploadToken||'');const path=String(prep.objectPath||'');if(!token||!path)throw Error('Supabase signed upload details are missing. Please retry the upload.');const {error}=await supabaseClient.storage.from(prep.bucketName).uploadToSignedUrl(path,token,file,{contentType:file.type||prep.contentType||'application/octet-stream',cacheControl:'3600'});if(error)throw Error(error.message||'Supabase Storage upload failed.');}
