async function replaceMedia(target,file){if(!file){const input=document.createElement('input');input.type='file';input.accept='image/png,image/jpeg,image/webp,image/gif,image/svg+xml,video/mp4,video/webm,video/quicktime';input.addEventListener('change',()=>{const selected=input.files?.[0];input.remove();if(selected)replaceMedia(target,selected)});document.body.appendChild(input);input.click();return}if(!confirm('Replace this media with the selected file? The existing Supabase object will be left untouched and the case-study reference will be updated safely.'))return;try{await directUploadMedia(file,{projectId:mediaState.project.id,replaceFixed:target.fixed,replaceImageId:target.imageId||target.id});await loadProjects();await loadMedia()}catch(e){alert(e.message)}}
