function openMediaEditor(x){x={...x,projectId:x.projectId||mediaState.project?.id||$('#mediaProject')?.value||''};const old=document.getElementById('mediaEditDialog');if(old)old.remove();const d=document.createElement('dialog');d.id='mediaEditDialog';d.className='media-edit-dialog';const isVideo=/\.(mp4|webm|mov)(\?|#|$)/i.test(String(x.image||''));const previewUrl=String(x.image||'');d.innerHTML=`<div class="editor-head"><div><div class="eyebrow">EDIT MEDIA</div><h2>${esc(x.label)}</h2><p class="muted">Preview the current media below. Hover over it to reveal the replacement control.</p></div><button class="icon-btn" type="button" data-close-edit>×</button></div><div class="media-edit-preview replace-preview" tabindex="0"><div class="media-preview-loading">Loading current media…</div><div class="media-preview-slot"></div><div class="media-preview-error" hidden>Preview unavailable. The media is still stored and can be replaced.</div><button class="replace-overlay" type="button" id="replaceFromEditor"><span>↻</span> Replace media</button><input id="replaceMediaFile" class="replace-file-input" type="file" accept="image/png,image/jpeg,image/webp,image/gif,image/svg+xml,video/mp4,video/webm,video/quicktime"></div>${x.fixed?'<div class="muted">This is a fixed case-study asset. Replace it here without changing its role.</div>':`<div class="form-grid"><label>Asset type<input value="${esc(x.label)}" disabled></label><label>Display order<input id="editMediaOrder" type="number" min="0" value="${x.order}"></label><label class="wide">Section<select id="editMediaSection"><option value="">Automatic section</option>${(mediaState.sections||[]).map(s=>`<option value="${esc(s.id)}">${esc(s.title||'Untitled section')}</option>`).join('')}</select></label><label class="wide">Alt text<input id="editMediaAlt" value="${esc(x.alt)}" placeholder="Describe the image for accessibility"></label><label class="wide">Caption<input id="editMediaCaption" value="${esc(x.caption)}" placeholder="Optional caption"></label></div>`}<div class="editor-actions"><span id="editMediaMsg" class="msg"></span><button class="secondary" type="button" data-close-edit>Cancel</button>${x.fixed?'':'<button class="primary" type="button" id="saveMediaInfo">Save changes</button>'}</div>`;document.body.appendChild(d);const editSection=d.querySelector('#editMediaSection');if(editSection&&x.sectionId&&[...editSection.options].some(o=>String(o.value)===String(x.sectionId)))editSection.value=String(x.sectionId);const close=()=>d.close();d.querySelectorAll('[data-close-edit]').forEach(b=>b.onclick=close);const slot=d.querySelector('.media-preview-slot');const loading=d.querySelector('.media-preview-loading');const error=d.querySelector('.media-preview-error');const finishPreview=()=>{loading.hidden=true;error.hidden=true};const failPreview=()=>{loading.hidden=true;error.hidden=false};let mediaEl;if(isVideo){mediaEl=document.createElement('video');mediaEl.controls=true;mediaEl.playsInline=true;mediaEl.preload='metadata';mediaEl.className='edit-media-content';mediaEl.src=API+'/admin-media-preview?project_id='+encodeURIComponent(x.projectId)+(x.fixed?'&fixed='+encodeURIComponent(x.fixed):'&image_id='+encodeURIComponent(x.id));mediaEl.addEventListener('loadeddata',finishPreview,{once:true});mediaEl.addEventListener('error',failPreview,{once:true})}else{mediaEl=document.createElement('img');mediaEl.className='edit-media-content';mediaEl.alt=x.alt||'';mediaEl.loading='eager';mediaEl.decoding='async';mediaEl.addEventListener('load',finishPreview,{once:true});mediaEl.addEventListener('error',failPreview,{once:true});mediaEl.src=API+'/admin-media-preview?project_id='+encodeURIComponent(x.projectId)+(x.fixed?'&fixed='+encodeURIComponent(x.fixed):'&image_id='+encodeURIComponent(x.id))}slot.appendChild(mediaEl);const replaceInput=d.querySelector('#replaceMediaFile');d.querySelector('#replaceFromEditor').onclick=()=>replaceInput.click();replaceInput.onchange=()=>{const file=replaceInput.files?.[0];if(file)replaceMedia(x.fixed?{fixed:x.fixed}:{imageId:x.id},file)};if(!x.fixed)d.querySelector('#saveMediaInfo').onclick=async()=>{const msgEl=d.querySelector('#editMediaMsg');msg(msgEl,'Saving…');try{await api('/admin-media',{method:'PATCH',body:JSON.stringify({id:x.id,project_id:x.projectId||mediaState.project?.id||'',caption:d.querySelector('#editMediaCaption').value,alt_text:d.querySelector('#editMediaAlt').value,display_order:Number(d.querySelector('#editMediaOrder').value)||0,section_id:d.querySelector('#editMediaSection')?.value||''})});msg(msgEl,'Saved to Supabase.');await loadMedia();setTimeout(close,250)}catch(e){msg(msgEl,e.message,true)}};d.addEventListener('close',()=>d.remove());d.showModal()}
