$('#mediaForm').onsubmit=async e=>{e.preventDefault();const projectId=$('#mediaProject').value;if(!projectId){msg($('#mediaMsg'),'Select a case study first.',true);return}const file=$('#mediaFile').files[0];if(!file){msg($('#mediaMsg'),'Choose a PNG, JPG, WebP, GIF, SVG, MP4, WebM, or MOV file.',true);return}const form=e.target;msg($('#mediaMsg'),'Uploading directly to Supabase Storage…');form.querySelector('button[type="submit"]').disabled=true;try{await directUploadMedia(file,{projectId,assetType:form.elements.asset_type.value,altText:form.elements.alt_text.value,caption:form.elements.caption.value,displayOrder:Number(form.elements.display_order.value)||0,sectionId:form.elements.section_id.value||''});msg($('#mediaMsg'),'Uploaded and saved to Supabase.');form.reset();populateMediaProjects(mediaState.project?.id||projectId);await loadProjects();$('#mediaProject').value=projectId;await loadMedia()}catch(err){msg($('#mediaMsg'),err.message,true)}finally{form.querySelector('button[type="submit"]').disabled=false}};
async function removeFixed(kind){if(!confirm('Remove this image from the case study?'))return;try{await api('/admin-media',{method:'DELETE',body:JSON.stringify({fixed:kind,project_id:mediaState.project.id})});await loadProjects();await loadMedia()}catch(e){alert(e.message)}}async function removeMedia(id){if(!confirm('Delete this image from Supabase Storage and the case study?'))return;try{await api('/admin-media',{method:'DELETE',body:JSON.stringify({id,project_id:mediaState.project?.id||''})});await loadMedia()}catch(e){alert(e.message)}}async function moveMedia(id,order){try{await api('/admin-media',{method:'PATCH',body:JSON.stringify({id,project_id:mediaState.project?.id||'',display_order:Number(order)||0})});await loadMedia()}catch(e){alert(e.message)}}
function formDataToObject(form){return Object.fromEntries(new FormData(form).entries())}
